import React, { useState, useCallback, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, MapPin } from 'lucide-react';
import { searchCities } from '../services/api';
import styles from './HeroSearch.module.css';

/* ── Mode tabs matching the reference image ───────────────────── */
const MODES = [
  { label: 'Buy',        listingType: 'Sell'  },
  { label: 'Rent',       listingType: 'Rent'  },
  { label: 'Commercial', buildingType: 'Commercial' },
  { label: 'PG/Hostel',  propertyType: 'pg'   },
  { label: 'Sell',       tab: 'sell'           },
];

/* ── Popular cities ──────────────────────────────────────────── */
const POPULAR_CITIES = [
  'Bengaluru', 'Mumbai', 'Hyderabad', 'Chennai', 'Pune', 'Delhi', 'Noida',
];

export default function HeroSearch() {
  const navigate = useNavigate();

  const [mode,           setMode]           = useState(0); // index into MODES
  const [city,           setCity]           = useState('');
  const [locality,       setLocality]       = useState('');
  const [suggestions,    setSuggestions]    = useState([]);
  const [suggestOpen,    setSuggestOpen]    = useState(false);
  const cityRef = useRef(null);

  // Close dropdown on outside click
  useEffect(() => {
    const handler = (e) => {
      if (cityRef.current && !cityRef.current.contains(e.target)) {
        setSuggestOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  /* City autocomplete */
  const handleCityInput = useCallback(async (e) => {
    const val = e.target.value;
    setCity(val);
    if (val.length >= 2) {
      setSuggestOpen(true);
      try {
        const { data } = await searchCities(val);
        setSuggestions(data.cities || []);
      } catch { setSuggestions([]); }
    } else {
      setSuggestions([]);
      setSuggestOpen(val.length > 0);
    }
  }, []);

  const pickCity = (c) => {
    setCity(c);
    setSuggestions([]);
    setSuggestOpen(false);
  };

  /* Search handler */
  const handleSearch = (e) => {
    e?.preventDefault();
    const params = new URLSearchParams();
    const m = MODES[mode];
    if (m.listingType)  params.set('listingType',  m.listingType);
    if (m.buildingType) params.set('buildingType', m.buildingType);
    if (m.propertyType) params.set('propertyType', m.propertyType);
    if (city)     params.set('city', city);
    if (locality) params.set('q',    locality);
    navigate('/search?' + params.toString());
  };

  const currentCity = city || 'India';

  return (
    <div className={styles.hero}>
      {/* Background house sketch (decorative) */}
      <div className={styles.bgSketch} />

      {/* Content */}
      <div className={styles.content}>

        {/* Heading — "Real Estate In [City]" */}
        <h1 className={styles.heading}>
          Real Estate In <span className={styles.cityHighlight}>{currentCity}</span>
        </h1>

        {/* Mode Tabs */}
        <div className={styles.tabRow}>
          {MODES.map((m, i) => (
            <button
              key={m.label}
              className={`${styles.tab} ${mode === i ? styles.tabActive : ''}`}
              onClick={() => setMode(i)}
            >
              {m.label}
            </button>
          ))}
        </div>

        {/* Search Bar */}
        <form className={styles.searchBar} onSubmit={handleSearch}>

          {/* City input with autocomplete */}
          <div className={styles.cityField} ref={cityRef}>
            <MapPin size={16} className={styles.cityIcon} />
            <input
              type="text"
              className={styles.cityInput}
              placeholder="Enter city..."
              value={city}
              onChange={handleCityInput}
              onFocus={() => { if (city.length >= 2 || suggestions.length > 0) setSuggestOpen(true); }}
              autoComplete="off"
            />

            {/* Autocomplete Dropdown */}
            {suggestOpen && (city.length >= 1) && (
              <ul className={styles.dropdown}>
                {suggestions.length > 0
                  ? suggestions.map(c => (
                    <li key={c} className={styles.dropItem} onMouseDown={() => pickCity(c)}>
                      <MapPin size={13} className={styles.dropIcon} />
                      <span>{c}</span>
                    </li>
                  ))
                  : POPULAR_CITIES
                      .filter(c => c.toLowerCase().startsWith(city.toLowerCase()))
                      .map(c => (
                        <li key={c} className={styles.dropItem} onMouseDown={() => pickCity(c)}>
                          <MapPin size={13} className={styles.dropIcon} />
                          <span>{c}</span>
                        </li>
                      ))
                }
              </ul>
            )}
          </div>

          {/* Divider */}
          <div className={styles.divider} />

          {/* Locality / Project search */}
          <div className={styles.localityField}>
            <input
              type="text"
              className={styles.localityInput}
              placeholder="Enter a location, builder, project..."
              value={locality}
              onChange={e => setLocality(e.target.value)}
            />
          </div>

          {/* Search button */}
          <button type="submit" className={styles.searchBtn}>
            <Search size={18} />
            Search
          </button>
        </form>

        {/* Popular cities quick-pick */}
        <div className={styles.popularRow}>
          <span className={styles.popularLabel}>Popular Cities:</span>
          {POPULAR_CITIES.map(c => (
            <button
              key={c}
              className={`${styles.popularChip} ${city === c ? styles.popularChipActive : ''}`}
              onClick={() => { setCity(c); }}
            >{c}</button>
          ))}
        </div>
      </div>
    </div>
  );
}
